const b = $input.first().json || {};
function day(x){ const s = String(x || '').trim(); if (!s) return null; const d = new Date(s.length === 10 ? s + 'T00:00:00' : s); return isNaN(d.getTime()) ? null : d; }
const co = day(b.check_out_date) || day(b.check_in_date);
const today = new Date(); today.setHours(0, 0, 0, 0);
const vac = [['rabies', b.rabies_expiry], ['DHPP', b.dhpp_expiry], ['bordetella', b.bordetella_expiry]];
const issues = [];
let allValid = true, borderline = false, minDays = 9999;
for (const pair of vac) {
  const name = pair[0], raw = pair[1];
  const d = day(raw);
  if (!d) { allValid = false; issues.push(name + ' record missing'); continue; }
  if (co && d.getTime() < co.getTime()) { allValid = false; issues.push(name + ' expires ' + String(raw).slice(0, 10) + ' before the stay ends'); }
  const days = Math.floor((d.getTime() - today.getTime()) / 86400000);
  if (days < minDays) minDays = days;
  if (co && d.getTime() >= co.getTime() && (d.getTime() - co.getTime()) <= 14 * 86400000) {
    borderline = true; issues.push(name + ' expires within 14 days of the stay');
  }
}
let compliance, decision;
if (!allValid) { compliance = 'noncompliant'; decision = 'blocked'; }
else if (borderline) { compliance = 'expiring_soon'; decision = 'conditional'; }
else { compliance = 'compliant'; decision = 'approved'; }
return [{ json: Object.assign({}, b, {
  compliance: compliance,
  decision: decision,
  issues: issues.length ? issues.join('; ') : 'All required vaccines are valid for the stay dates.',
  min_expiry_days: minDays === 9999 ? '' : String(minDays)
}) }];

const out = [];
const base = ($('Check Vaccine Validity').first() || {}).json || {};
for (const it of $input.all()) {
  const p = it.json || {};
  const raw = String(p.output || '').trim();
  let parsed = {};
  try { parsed = JSON.parse(raw); } catch (e) { parsed = {}; }
  out.push(Object.assign({}, base, {
    email_subject: String(parsed.subject || ('Your boarding request for ' + (base.pet_name || 'your pet'))).trim(),
    email_body: String(parsed.body || raw || '').trim()
  }));
}
return out;

const rows = ($input.all() || []).map(function(r){ return r.json || {}; }).filter(function(r){ return String(r.owner_email || '').trim(); });
const today = new Date(); today.setHours(0, 0, 0, 0);
function day(x){ const s = String(x || '').trim(); if (!s) return null; const d = new Date(s.length === 10 ? s + 'T00:00:00' : s); return isNaN(d.getTime()) ? null : d; }
const map = new Map();
for (const r of rows) {
  const key = String(r.owner_email || '').toLowerCase() + '|' + String(r.pet_name || '').toLowerCase();
  const prev = map.get(key);
  if (!prev || String(r.received_at || '') > String(prev.received_at || '')) { map.set(key, r); }
}
const out = [];
for (const r of map.values()) {
  const vac = [['rabies', r.rabies_expiry], ['DHPP', r.dhpp_expiry], ['bordetella', r.bordetella_expiry]];
  let soonest = null, soonestName = '', soonestDays = 9999;
  for (const pair of vac) {
    const d = day(pair[1]); if (!d) continue;
    const days = Math.floor((d.getTime() - today.getTime()) / 86400000);
    if (days < soonestDays) { soonestDays = days; soonest = pair[1]; soonestName = pair[0]; }
  }
  if (soonest && soonestDays <= 30) {
    const dueTxt = soonestDays < 0 ? 'has already expired' : ('expires in ' + soonestDays + ' day(s)');
    const dateTxt = String(soonest).slice(0, 10);
    out.push({ json: Object.assign({}, r, {
      expiring_vaccine: soonestName,
      expiring_date: dateTxt,
      days_to_expiry: soonestDays,
      reminder_subject: r.pet_name + ' vaccine ' + soonestName + (soonestDays < 0 ? ' has expired' : ' expires soon'),
      reminder_body: ['Hi ' + (r.owner_name || 'there') + ',', '', 'A friendly reminder from the boarding team. ' + (r.pet_name || 'Your pet') + ' has a ' + soonestName + ' vaccination record on file that ' + dueTxt + ' (' + dateTxt + ').', '', 'Every guest must be current on rabies, DHPP and bordetella before drop off. Please ask your vet to send an updated record so the next stay is not delayed.', '', 'Thank you,', 'Boarding team'].join(String.fromCharCode(10))
    }) });
  }
}
return out;

const rows = ($input.all() || []).map(function(r){ return r.json || {}; }).filter(function(r){ return String(r.pet_name || '').trim(); });
const today = new Date(); today.setHours(0, 0, 0, 0);
function day(x){ const s = String(x || '').trim(); if (!s) return null; const d = new Date(s.length === 10 ? s + 'T00:00:00' : s); return isNaN(d.getTime()) ? null : d; }
const counts = { approved: 0, conditional: 0, blocked: 0 };
let expiring = 0;
const attention = [];
for (const r of rows) {
  const d = String(r.decision || '').toLowerCase();
  if (counts[d] !== undefined) { counts[d]++; }
  const vac = [r.rabies_expiry, r.dhpp_expiry, r.bordetella_expiry];
  for (const raw of vac) {
    const dd = day(raw); if (!dd) continue;
    const days = Math.floor((dd.getTime() - today.getTime()) / 86400000);
    if (days <= 30) { expiring++; break; }
  }
  if (d !== 'approved') { attention.push((r.pet_name || '') + ' (' + (r.owner_name || '') + '): ' + (r.issues || '')); }
}
return [{ json: {
  week_of: $now.toFormat('yyyy-MM-dd'),
  total_bookings: rows.length,
  approved: counts.approved,
  conditional: counts.conditional,
  blocked: counts.blocked,
  pets_expiring_30d: expiring,
  attention_list: attention.slice(0, 12).join(' | ') || 'None',
  kennel_email: rows.length ? (rows[rows.length - 1].kennel_email || 'user@example.com') : 'user@example.com'
}}];

const out = [];
const base = ($('Summarize Bookings').first() || {}).json || {};
for (const it of $input.all()) {
  const p = it.json || {};
  const raw = String(p.output || '').trim();
  let parsed = {};
  try { parsed = JSON.parse(raw); } catch (e) { parsed = {}; }
  out.push({ json: Object.assign({}, base, {
    email_subject: String(parsed.subject || 'Weekly boarding digest').trim(),
    email_body: String(parsed.body || raw || '').trim()
  }) });
}
return out;
